; AMY Rev C self-contained 6502 audio feature test. Generated by create_test.py.
; Atari executable .XEX; start at $4000, no BASIC or CIO required.
; Each case produces 0.5s of audio followed by 0.1s of silence.
; PAL 50Hz: 25 + 5 video frames; NTSC 60Hz: 30 + 6 frames.
; Uses OS RTCLOK low byte ($14) for timing; do not disable VBI/IRQ.
; Read full test list and nominal timing in MANIFEST.csv.
; Uses 8.192MHz Rev C AMY, 8 voices x 8 harmonics, $D2C0-$D2CF.
;
.org $4000
AMY = $D2C0
VOL = $D2C6
EC_STATUS = $D2CE
RTCLOK_LO = $0014
PALREG = $D014
PTRLO = $0080
PTRHI = $0081
INDEX = $0082
N_ON = $0083
N_GAP = $0084
N_LEAD = $0085
START_FRAME = $0086
GAP_FRAME = $0087
DURATION = $0088

ENTRY:
    LDA #$00
    STA VOL
    STA INDEX
    ; PALREG bits 1-3 nonzero = PAL machine, as in amyconv.
    LDA PALREG
    AND #$0E
    BEQ NTSC_MODE
PAL_MODE:
    LDA #$19        ; 25 frames = 0.5 second PAL
    STA N_ON
    LDA #$05
    STA N_GAP
    LDA #$32        ; 50 frames lead in = 1 second
    STA N_LEAD
    JMP SETUP_FIRST
NTSC_MODE:
    LDA #$1E        ; 30 frames = 0.5 second NTSC
    STA N_ON
    LDA #$06
    STA N_GAP
    LDA #$3C
    STA N_LEAD
SETUP_FIRST:
    JSR EXEC_SCRIPT
    LDA N_LEAD
    JSR WAIT_FRAMES
PLAY_CASE:
    ; Frame alignment makes section times deterministic to one video frame.
    LDA RTCLOK_LO
ALIGN:
    CMP RTCLOK_LO
    BEQ ALIGN
PLAY_NOALIGN:
    LDX INDEX
    LDA CASE_GAIN,X ; default $20, half-level diagnostic $10
    STA VOL
    LDA N_ON
    JSR WAIT_FRAMES
    LDA #$00
    STA VOL         ; immediate mute, even if a release envelope continues
    INC INDEX
    LDA INDEX
    CMP #NUM_CASES
    BEQ FINISH
    LDA RTCLOK_LO
    STA GAP_FRAME
    JSR EXEC_SCRIPT  ; reprogram AMY inside the silent interval
    LDA GAP_FRAME
    STA START_FRAME
    LDA N_GAP
    JSR WAIT_FROM_START
    JMP PLAY_NOALIGN
FINISH:
    ; Final silence, then return to DOS if it installed a RUN vector.
    LDA #$00
    STA VOL
    LDA N_GAP
    JSR WAIT_FRAMES
    RTS

WAIT_FRAMES:
    ; Input A = number of video frames to wait from now.
    PHA
    LDA RTCLOK_LO
    STA START_FRAME
    PLA
WAIT_FROM_START:
    ; Input A = frames; START_FRAME set by caller.
    STA DURATION
WAIT_LOOP:
    LDA RTCLOK_LO
    SEC
    SBC START_FRAME
    CMP DURATION
    BCC WAIT_LOOP
    RTS

EXEC_SCRIPT:
    ; Find the indexed script pointer.
    LDA INDEX
    ASL A
    TAX
    LDA CASE_PTRS,X
    STA PTRLO
    LDA CASE_PTRS+1,X
    STA PTRHI
CMD_LOOP:
    JSR NEXT_BYTE
    CMP #$FF
    BEQ SCRIPT_END
    CMP #$FE
    BEQ SCRIPT_AMY_IDLE
    CMP #$FD
    BEQ SCRIPT_ENG_IDLE
    TAX              ; destination offset 0..15
    JSR NEXT_BYTE    ; A = value
    CPX #$04
    BCS WRITE_NOW
FIFO_WAIT:
    ; BIT loads V with status bit6 = FIFO full.
    BIT AMY
    BVS FIFO_WAIT
WRITE_NOW:
    STA AMY,X
    JMP CMD_LOOP
SCRIPT_AMY_IDLE:
    JSR WAIT_AMY_IDLE
    JMP CMD_LOOP
SCRIPT_ENG_IDLE:
    JSR WAIT_ENGINE_IDLE
    JMP CMD_LOOP
SCRIPT_END:
    RTS

NEXT_BYTE:
    LDY #$00
    LDA (PTRLO),Y
    INC PTRLO
    BNE BYTE_OK
    INC PTRHI
BYTE_OK:
    RTS
WAIT_AMY_IDLE:
    BIT AMY
    BMI WAIT_AMY_IDLE
    RTS
WAIT_ENGINE_IDLE:
    BIT EC_STATUS
    BMI WAIT_ENGINE_IDLE
    RTS

NUM_CASES = 37
CASE_PTRS:
    .word CASE_00
    .word CASE_01
    .word CASE_02
    .word CASE_03
    .word CASE_04
    .word CASE_05
